// Heads of Terms on a Letting Tracker unit (Woody, 2026-11-12).
//
// The flow: a property has a STANDARD set of HOTs (uploaded, or made with
// "Create standard HOTs" from the text below). Once an offer's terms are
// agreed, HOTs are GENERATED by filling the standard from that offer, the
// unit and its Targeting Brief. Everyone on the brief can amend the draft;
// each amendment raises the version. When everyone has agreed the current
// version the HOTs can be ISSUED to the tenant. The negotiation on the HOTs
// themselves happens outside the app; the FINAL agreed HOTs are uploaded and
// the deal moves to Solicitors.

export const HOTS_TOKENS = [
  { token: "PROPERTY", meaning: "Property or scheme name" },
  { token: "UNIT", meaning: "Unit name" },
  { token: "AREA", meaning: "Unit size" },
  { token: "DATE", meaning: "Today's date" },
  { token: "LANDLORD", meaning: "Landlord company" },
  { token: "TENANT", meaning: "Tenant brand (from the agreed offer)" },
  { token: "TENANT_CONTACT", meaning: "Tenant's contact on the offer" },
  { token: "RENT", meaning: "Agreed rent a year" },
  { token: "TURNOVER_RENT", meaning: "Turnover rent percentage" },
  { token: "TERM", meaning: "Lease term" },
  { token: "BREAK", meaning: "Break option" },
  { token: "RENT_FREE", meaning: "Rent-free period" },
  { token: "CAPITAL_CONTRIBUTION", meaning: "Landlord's capital contribution" },
  { token: "FIT_OUT", meaning: "Same as CAPITAL_CONTRIBUTION (older templates)" },
  { token: "PREMIUM", meaning: "Premium" },
  { token: "RENT_REVIEW", meaning: "Rent review pattern" },
  { token: "RENT_DEPOSIT", meaning: "Rent deposit" },
  { token: "INCENTIVES", meaning: "Other incentives" },
  { token: "SERVICE_CHARGE", meaning: "Service charge a year" },
  { token: "RATES", meaning: "Rates payable a year" },
  { token: "INSURANCE", meaning: "Insurance a year" },
  { token: "USE", meaning: "Permitted use" },
  { token: "OFFER_DATE", meaning: "Date of the agreed offer" },
  { token: "LANDLORD_AGENT", meaning: "BGP agents on the brief" },
  { token: "JOINT_AGENT", meaning: "Joint agent on the brief" },
  { token: "LANDLORD_CONTACT", meaning: "Client leasing contacts on the brief" },
] as const;
export type HotsToken = (typeof HOTS_TOKENS)[number]["token"];
export type HotsValues = Partial<Record<HotsToken, string | null | undefined>>;

// What an empty token reads as in the draft, so a gap is obvious to the
// person amending it and never looks like an agreed term.
const GAP: Record<HotsToken, string> = {
  PROPERTY: "[property]", UNIT: "[unit]", AREA: "[area]", DATE: "[date]", LANDLORD: "[landlord]",
  TENANT: "[tenant]", TENANT_CONTACT: "[tenant contact]", RENT: "[rent]", TURNOVER_RENT: "[turnover rent, if any]",
  TERM: "[term]", BREAK: "[break option]", RENT_FREE: "[rent free]", CAPITAL_CONTRIBUTION: "[capital contribution]",
  FIT_OUT: "[capital contribution]", PREMIUM: "[premium]", RENT_REVIEW: "[rent review]", RENT_DEPOSIT: "[rent deposit]",
  INCENTIVES: "[other incentives]", SERVICE_CHARGE: "[service charge]", RATES: "[rates payable]", INSURANCE: "[insurance]",
  USE: "[permitted use]", OFFER_DATE: "[offer date]", LANDLORD_AGENT: "[landlord's agent]", JOINT_AGENT: "[joint agent]",
  LANDLORD_CONTACT: "[landlord contact]",
};

// Fill `{TOKEN}` placeholders. Unknown tokens are left as written.
export function fillHotsTemplate(template: string, values: HotsValues): { text: string; gaps: HotsToken[] } {
  const gaps = new Set<HotsToken>();
  const text = template.replace(/\{([A-Z_]+)\}/g, (whole, name: string) => {
    if (!(name in GAP)) return whole;
    const token = name as HotsToken;
    const v = values[token];
    if (v === null || v === undefined || String(v).trim() === "") { gaps.add(token); return GAP[token]; }
    return String(v);
  });
  return { text, gaps: [...gaps] };
}

// Gaps still showing in a draft (square-bracket placeholders), for the
// "still to fill" note before sign-off.
export function hotsGapsIn(text: string): string[] {
  const out = new Set<string>();
  for (const m of text.matchAll(/\[[a-z][a-z ,'’]{2,40}\]/g)) out.add(m[0]);
  // A scheme's own form marks blanks as "[ ]" or runs of X.
  const blanks = (text.match(/\[\s*\]/g) || []).length + (text.match(/\bX{2,}\b/g) || []).length;
  if (blanks > 0) out.add(`${blanks} ${blanks === 1 ? "blank" : "blanks"} marked [ ] or XXXX`);
  return [...out];
}

// The standard set of HOTs behind "Create standard HOTs". The clause list
// follows the heads of terms BGP issues for Landsec (37 clauses, the 2025
// Deptford form on the share drive); the deal-specific figures are tokens.
// A property's own standard replaces this once uploaded or edited.
export const STANDARD_HOTS_TEMPLATE = `HEADS OF TERMS
Subject to Contract

{UNIT}, {PROPERTY}
Date: {DATE}

1. Timescale
The parties agree to aim to exchange contracts within 3 weeks of receipt of the legal pack (which may be in electronic form), and have agreed that an all-parties meeting or conference call will take place 2 weeks after receipt, unless legal documentation is agreed before then.

2. Unit
{UNIT}, {PROPERTY}
Accommodation: {AREA}

3. Landlord
{LANDLORD}
Company number: [company number]
Registered office: [registered office]

4. Tenant
{TENANT}
Company number: [company number]
Trading as: [trading name]
Contact details: {TENANT_CONTACT}

5. Access and lease completion
The tenant will be given access to the unit for shop fitting when the lease completes. This is the Access Date.

6. Fit out
The tenant will comply with the shop fitting guide. The landlord's approval of the shop front will not be unreasonably withheld. The tenant must supply as-built drawings (in both PDF and DWG formats) within one week of opening for trade.

7. Tenant's opening for trade
The tenant must complete its fit out and open for trade in the agreed trading brand no later than [number] weeks after the Access Date. During its fit out the tenant will provide appropriate hoarding or vinyls to the shop front.

8. Lease term
{TERM} from the quarter day after the Access Date. The lease will be outside the Landlord and Tenant Act 1954.

9. Break option
{BREAK}

10. Rent
{RENT} per annum exclusive of VAT, rates and all other outgoings, payable by equal payments monthly in advance by BACS.
Turnover rent: {TURNOVER_RENT}

11. Rent deposit
{RENT_DEPOSIT}
The deposit, plus a sum equal to VAT at the prevailing rate, is to be held by the landlord and will revert to the landlord in the event of insolvency in acknowledgment of the landlord's costs for marketing and any contribution or other payment to a replacement tenant.

12. Capital contribution
{CAPITAL_CONTRIBUTION}
Payable against the necessary receipts, in stages to be agreed.

13. Rent commencement date
Rent free: {RENT_FREE}
Insurance and service charge rents and all other sums are payable from the Access Date.

14. Rent review
{RENT_REVIEW}

15. Turnover information
The tenant will provide turnover information quarterly.

16. Repair and reinstatement
The tenant will be required to keep the unit in good and substantial repair and condition. At the end of the term the tenant shall be required to remove any alterations it has made unless the landlord otherwise directs.

17. Service charge
The tenant will pay a fair proportion of the service charge including CRC costs attributable to the energy used in the common parts. On account payments of service charge will be made quarterly in advance and will be subject to annual reconciliation.
Service charge is estimated at {SERVICE_CHARGE} per annum.

18. Insurance
The landlord will insure and recover a fair proportion of the premium costs from the tenant. Estimated at {INSURANCE} per annum.

19. Damage by uninsured risks
In relation to damage by risks which are uninsured, the tenant's position will generally be the same as if insurance was in place, although the landlord can terminate the lease instead of reinstating at its own cost.

20. User
{USE}

21. Alienation
Assignment of the whole is permitted with the landlord's consent, not to be unreasonably withheld or delayed. No assignment of part. [Any further restrictions to be confirmed.]

22. Group sharing
Occupation of the unit by group companies of the tenant is permitted as long as the occupier remains related to the tenant and no relationship of landlord and tenant is created. The tenant must not share occupation with any other party.

23. Pre-emption
The landlord will have a right of pre-emption on assignment on the same terms as offered by a proposed assignee.

24. Alterations
The tenant must not build any new structure, alter the external appearance of the unit nor cut into any structural part of the building. The installation and removal of demountable partitioning do not require consent. Any other alterations, including those to the shop front, require the landlord's consent, not to be unreasonably withheld or delayed.

25. Sustainability
The landlord and the tenant agree to work together with the aim of improving the environmental performance of the centre and the premises. The tenant agrees to allow the landlord to install separate metering of utilities at the landlord's own cost. The landlord and the tenant agree to share data in relation to environmental performance at least annually.

26. Interest on late payment
Interest at 3% above the base lending rate of Lloyds Bank will be payable on overdue sums due under the terms of the lease.

27. VAT
VAT will be payable on all rents and outgoings.

28. Legal costs
Each party is to bear their own legal costs.

29. Landlord's solicitors
[name, firm, telephone, email]

30. Tenant's solicitors
[name, firm, telephone, email]

31. Landlord's agents
{LANDLORD_AGENT}
Joint agent: {JOINT_AGENT}

32. Landlord contact
{LANDLORD_CONTACT}

33. Tenant contact
{TENANT_CONTACT}

34. Landlord's co-ordinator
[name, telephone, email]

35. Marketing
The tenant agrees that its name may be used by the landlord in all letting and marketing.

36. Confidentiality
The tenant may not disclose to any third party the content of these heads of terms and the agreement for lease to be entered into between the parties without the consent of the landlord.

37. Other conditions
1. Subject to contract
2. Landlord's board approval
Other incentives: {INCENTIVES}
Rates payable are estimated at {RATES} per annum.

It is acknowledged that in agreeing these heads of terms, the parties have had regard to the provisions of the Code for Leasing Business Premises in England & Wales.
`;

export type HotsStage = "no_template" | "no_draft" | "draft" | "agreed" | "issued" | "final";

export interface HotsSigner {
  briefPersonId: string;
  role: string;
  name: string;
  firm: string | null;
  userId: string | null;
  isMe: boolean;                 // this row is the person looking
  agreedAt: string | null;       // on the CURRENT version only
  staleAgreedAt: string | null;  // agreed an earlier version
  agreedByName: string | null;
  agreedOnBehalf: boolean;
}

export interface HotsEvent {
  id: string; kind: string; body: string | null; version: number | null;
  authorName: string | null; authorRole: string | null; createdAt: string | null;
}

export interface HotsWorkspace {
  unit: { id: string; unitName: string; propertyId: string | null; propertyName: string | null; marketingStatus: string | null; dealId: string | null; dealRef: string | null };
  stage: HotsStage;
  // isStandard: the text equals a built-in standard (BGP's, or the scheme's own form). standardName names it.
  // schemeStandardName: this property's scheme has its own built-in form, which Create standard HOTs uses.
  template: { text: string | null; docxName: string | null; isStandard: boolean; standardName?: string | null; schemeStandardName?: string | null };
  content: string | null;
  version: number;
  updatedAt: string | null;
  gaps: string[];                                   // placeholders still in the draft
  offer: { id: string; companyName: string | null; status: string; offerDate: string; rentPa: number | null } | null;   // the offer the draft was generated from
  agreedOffer: { id: string; companyName: string | null; offerDate: string; rentPa: number | null } | null;            // the unit's agreed offer, if one is
  // The offer the draft came from has changed since the draft was last generated or amended (it was reopened,
  // re-agreed on other terms, rejected...), or is no longer agreed: the draft may not match the agreed terms.
  offerOutOfStep?: boolean;
  briefId: string | null;
  signers: HotsSigner[];
  approval: { total: number; agreed: number; complete: boolean };
  agreedAt: string | null;
  issuedAt: string | null; issuedByName: string | null;
  finalFile: { id: string; fileName: string; url: string; uploadedAt: string | null; uploadedByName: string | null } | null;
  events: HotsEvent[];                               // oldest first
  // isStaff: a BGP login. It opens BGP's own records (the CRM picker on the
  // convert form, the KYC request) and is never true for a joint agent.
  // agentControl: the agents running the letting, BGP staff or a joint agent
  // on a scheme they are instructed on. It is what the action buttons follow:
  // record an agreement for someone with no login, reopen, upload or remove
  // the final file (and, through canManageTemplate, canIssue and canConvert,
  // the standard, issuing and the conversion).
  viewer: { isStaff: boolean; agentControl?: boolean; canEdit: boolean; canManageTemplate: boolean; canIssue: boolean; canConvert: boolean };
  // What the Convert to Solicitors form starts from: the terms of the offer
  // the HOTs came from (or the unit's agreed offer). For the agents running
  // the letting only, and only once the final HOTs are uploaded.
  convertDefaults?: HotsConvertDefaults | null;
  // Set once the unit is at Solicitors (or past it) with its final HOTs on
  // file: the deal it became and where its AML stands.
  conversion?: HotsConversion | null;
}

export interface HotsConvertDefaults {
  tenantCompanyId: string | null;   // BGP staff only: null for a joint agent
  tenantLinked?: boolean;           // a CRM company is linked (on the agreed offer or the deal)
  tenantName: string | null;
  rentPa: number | null;
  leaseLengthYears: number | null;
  rentFreeMonths: number | null;
  breakOption: string | null;
  capitalContribution: number | null;
}

// The answer of POST /api/unit-hots/:unitId/convert, and what the workspace
// carries afterwards. tenantCompanyId is given to BGP staff only; dealUrl is
// null for a login that has no deal page (a joint agent).
// A joint agent's aml line says only that the checks have started (neutral):
// nothing about a counterparty or where its checks stand.
export interface HotsConversion {
  dealId: string;
  dealRef: number | null;
  dealUrl: string | null;
  tenantCompanyId: string | null;
  tenantName: string | null;
  aml: { ok: boolean; message: string | null; neutral?: boolean };
  statusWarning?: string | null;
}
